startBuild = async function() {
  var data, err, resp;
  els.buildBtn.disabled = true;
  els.flashBtn.disabled = true;
  firmwareBytes = null;
  currentRunId = null;
  els.log.textContent = "";
  setStatus("Dispatching build…", "busy");
  els.runLink.classList.add("hidden");
  els.progressWrap.classList.add("hidden");
  try {
    resp = (await fetch(API_BASE + "/api/build", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify(collectParams())
    }));
    data = (await resp.json());
    if (!resp.ok) {
      throw new Error(data.error || "HTTP " + resp.status);
    }
    currentRunId = data.run_id;
    if (data.html_url) {
      els.runLink.href = data.html_url;
      els.runLink.classList.remove("hidden");
    }
    setStatus("Build queued — waiting for GitHub Actions…", "busy");
    return poll();
  } catch (error) {
    err = error;
    setStatus("Build failed: " + err.message, "fail");
    return els.buildBtn.disabled = false;
  }
};

poll = async function() {
  var data, err, resp;
  if (!currentRunId) {
    return;
  }
  try {
    resp = (await fetch(API_BASE + "/api/build/" + currentRunId));
    data = (await resp.json());
    if (!resp.ok) {
      throw new Error(data.error || "HTTP " + resp.status);
    }
    if (!data.ready) {
      setStatus("Building… (" + (data.status || "queued") + ")", "busy");
      setTimeout(poll, 5000);
      return;
    }
    if (data.conclusion !== "success") {
      setStatus("Build " + data.conclusion + " — check the GitHub run.", "fail");
      els.buildBtn.disabled = false;
      return;
    }
    setStatus("Build complete — ready to flash.", "done");
    els.buildBtn.disabled = false;
    return els.flashBtn.disabled = false;
  } catch (error) {
    err = error;
    setStatus("Polling error: " + err.message, "fail");
    return els.buildBtn.disabled = false;
  }
};

downloadFirmware = async function() {
  var buf, err, resp;
  setStatus("Downloading firmware…", "busy");
  resp = (await fetch(API_BASE + "/api/build/" + currentRunId + "/download"));
  if (!resp.ok) {
    err = (await resp.json().catch(function() {
      return {
        error: "HTTP " + resp.status
      };
    }));
    throw new Error(err.error || "HTTP " + resp.status);
  }
  buf = (await resp.arrayBuffer());
  firmwareBytes = new Uint8Array(buf);
  return log("Firmware: " + firmwareBytes.length + " bytes (merged image @ 0x0000)");
};

terminal = function() {
  return {
    clean: function() {
      return els.log.textContent = "";
    },
    writeLine: function(d) {
      return log(d);
    },
    write: function(d) {
      return els.log.textContent += d;
    }
  };
};

